// Presentation only. The working kiosk retains its own request/voice/erase controllers.
document.querySelectorAll('[data-open-details]').forEach(link => {
  link.addEventListener('click', event => {
    const target = document.querySelector(link.getAttribute('href'));
    if (target instanceof HTMLDetailsElement) {
      event.preventDefault();
      target.open = true;
      target.scrollIntoView({ block: 'start' });
      target.querySelector('summary')?.focus({ preventScroll: true });
    }
  });
});

// One request owner for this landing surface; future language/voice adapters must
// consume it rather than start another controller. The kiosk has its own owner.
const ballotForm = document.getElementById('ballot-form');
if (ballotForm && window.OpenOracleIntake) {
  window.OpenOracleWebsiteOwner = window.OpenOracleIntake.createOwner();
  window.OpenOracleIntake.mount(ballotForm, window.OpenOracleWebsiteOwner);
}

// Presentation only: one scroll-driven change; no request, capture, session or player.
(()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const hero=document.getElementById('promise'),marker=document.getElementById('clear-writing');if(!hero||!marker)return;let done=false,scheduled=false;function update(){scheduled=false;if(!done&&marker.getBoundingClientRect().top<innerHeight*.65){hero.classList.add('hero-second');done=true;removeEventListener('scroll',queue);}}function queue(){if(!scheduled){scheduled=true;requestAnimationFrame(update);}}addEventListener('scroll',queue,{passive:true});update();})();

